edits.before:
this._setupDismiss()

// Set initial value if input has a value
if (this._isInput && this._element.value) {
  this._parseInputValue()
}

edits.after:
this._setupDismiss()

// Hide datepicker on Tab key press to allow focus to leave the input
if (this._isInput && !this._isInline) {
  this._onTabKey = (event: KeyboardEvent) => {
    if (event.key === 'Tab' && this._isShown) {
      this.hide();
    }
  };
  EventHandler.on(this._element, 'keydown', this._onTabKey);
}

// Set initial value if input has a value
if (this._isInput && this._element.value) {
  this._parseInputValue()
}

edits.before:
if (this._onTriggerClick) {
  EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
}

if (this._calendar) {
  this._calendar.destroy()
}

edits.after:
if (this._onTriggerClick) {
  EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
}

// Clean up Tab key listener
if (this._onTabKey) {
  EventHandler.off(this._element, 'keydown', this._onTabKey)
  this._onTabKey = null
}

if (this._calendar) {
  this._calendar.destroy()
}
